import paradox.music.nativeui.*;import android.os.*;import java.util.concurrent.*;import java.lang.reflect.*;import java.nio.file.*;import java.util.zip.*;import java.io.*;
public class SweepHarness{
 static class Target{public int twice(int i){if(Looper.myLooper()!=Looper.getMainLooper())throw new AssertionError("not main");return i*2;}public void fail(){throw new IllegalStateException("expected");}public void fatal(){throw new LinkageError("expected error");}}
 static void pump(Thread t)throws Exception{for(int i=0;i<1000&&t.isAlive();i++){Handler.drain();Thread.sleep(2);}if(t.isAlive())throw new AssertionError("worker stuck");}
 public static void main(String[]a)throws Exception{Looper.getMainLooper();Target target=new Target();if(!NativeMusicMainThread.invoke(target,"twice",new Class[]{int.class},new Object[]{2}).equals(4))throw new AssertionError();final Throwable[] err={null};Thread t=new Thread(()->{try{if(!NativeMusicMainThread.invoke(target,"twice",new Class[]{int.class},new Object[]{3}).equals(6))throw new AssertionError();try{NativeMusicMainThread.invoke(target,"fail",new Class[0],new Object[0]);throw new AssertionError("no failure");}catch(IllegalStateException expected){}try{NativeMusicMainThread.invoke(target,"fatal",new Class[0],new Object[0]);throw new AssertionError("no error");}catch(LinkageError expected){} }catch(Throwable e){err[0]=e;}});t.start();pump(t);if(err[0]!=null)throw new AssertionError(err[0]);System.out.println("PASS main/worker dispatch, primitive return, lifecycle exception and Error propagate without stranded worker");
 Class<?> entry=Class.forName("paradox.music.nativeui.NativeMusicActivity");Method init=entry.getDeclaredMethod("ensureApplicationCreated",MusicPluginLoader.class);init.setAccessible(true);MusicPluginLoader plugin=new MusicPluginLoader();MusicPluginLoader.fail=a[0].equals("failure");Thread worker=new Thread(()->{for(int i=0;i<2;i++)try{init.invoke(null,plugin);}catch(Exception expected){if(!MusicPluginLoader.fail)err[0]=expected;}});worker.start();pump(worker);if(err[0]!=null||MusicPluginLoader.count!=1)throw new AssertionError("Application count "+MusicPluginLoader.count,err[0]);System.out.println("PASS Application initialization is at most once after "+a[0]);
 File zip=File.createTempFile("abi-fixture",".zip");try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(zip))){for(String abi:new String[]{"armeabi-v7a","arm64-v8a"}){z.putNextEntry(new ZipEntry("lib/"+abi+"/libfixture.so"));z.write(new byte[]{1});z.closeEntry();}}Method select=entry.getDeclaredMethod("selectAbiPrefix",ZipFile.class);select.setAccessible(true);try(ZipFile z=new ZipFile(zip)){if(!"lib/arm64-v8a/".equals(select.invoke(null,z)))throw new AssertionError("wrong process ABI");}System.out.println("PASS 64-bit process selection ignores leading device 32-bit ABI");
 Class<?> diag=Class.forName("paradox.music.nativeui.NativeMusicDiagnostics");Method summary=diag.getDeclaredMethod("displaySummary",String.class);summary.setAccessible(true);StringBuilder big=new StringBuilder();for(int i=0;i<50000;i++)big.append("Synthetic diagnostic line "+i+"\n");String text=(String)summary.invoke(null,big.toString());if(text.length()>13*1024||text.split("\n").length>105)throw new AssertionError("unbounded summary");System.out.println("PASS 50000-line report bounded below 13KB and 105 lines");System.exit(0);}}
